import { useCallback, useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { ChevronRight } from "lucide-react";

/* ------------------------------------------------------------------ */
/* Trending Destinations rail — the first section on /travel.         */
/* Data: public/data/travel-destinations.json (destination tracker,   */
/* generated by pipeline/build-travel-destinations.py) — the rail     */
/* renders its trending_now ranking with the tracker's own labeled    */
/* score reasons as chips. Hero photos come from the tracker's        */
/* hero_image, falling back to the guide galleries                    */
/* (public/data/travel-galleries.json); destinations without a real   */
/* photo get a navy monogram block — never an invented image.         */
/*                                                                    */
/* Tiering (Kiran, 2026-10-14): USA-group destinations are eligible   */
/* only if top-tier (Hawaii, Alaska, Yellowstone). The slug allowlist */
/* below is a belt-and-braces filter on top of the dataset's own      */
/* eligibility flag, so the rail is correct whichever data            */
/* regeneration lands first. International + India are all eligible.  */
/* ------------------------------------------------------------------ */

const TOP_TIER_USA = new Set(["hawaii", "alaska", "yellowstone"]);
const MAX_CARDS = 8;
const GAP = 16;

type TrendingComponent = {
  id: string;
  points: number | null;
  max: number;
  reason: string;
};

type FareFrom = {
  price_min: number;
  route: string;
  origin_metro: string;
  dest_metro: string;
  date_range: string;
  weeks: number;
  as_of: string;
} | null;

type TrendingDestination = {
  slug: string;
  name: string;
  guide_url: string;
  group: "india" | "usa" | "international";
  region: string;
  best_months: number[];
  season_note: string;
  hero_image: string | null;
  fare_from: FareFrom;
  highlights: { title: string; snippet: string }[];
  trending: {
    score: number;
    max_score: number;
    components: TrendingComponent[];
  };
  eligible_for_picks?: boolean;
};

type DestinationsData = {
  generated_at: string;
  current_month: number;
  current_year: number;
  trending_now: string[];
  destinations: TrendingDestination[];
};

type GalleryData = Record<string, { photos: { src: string; caption: string }[] }>;

let destCache: Promise<DestinationsData | null> | null = null;
function loadDestinations(): Promise<DestinationsData | null> {
  if (!destCache) {
    destCache = fetch("/data/travel-destinations.json")
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return destCache;
}

let galleryCache: Promise<GalleryData | null> | null = null;
function loadGalleries(): Promise<GalleryData | null> {
  if (!galleryCache) {
    galleryCache = fetch("/data/travel-galleries.json")
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return galleryCache;
}

function isEligible(d: TrendingDestination): boolean {
  if (typeof d.eligible_for_picks === "boolean") return d.eligible_for_picks;
  if (d.group === "usa") return TOP_TIER_USA.has(d.slug);
  return true;
}

/* Short chip labels for the tracker's positive signals only. The full
   reason sentence rides along as the chip's title so nothing is hidden:
   fare_drop earns a chip only when its points are actually positive —
   a tracked route with no drop (0) or no route at all (null) gets none. */
function reasonChips(d: TrendingDestination): { label: string; title: string }[] {
  const chips: { label: string; title: string }[] = [];
  for (const c of d.trending.components) {
    if (c.points == null) continue;
    if (c.id === "season_fit" && c.points >= 40) {
      chips.push({ label: "In season now", title: c.reason });
    } else if (c.id === "season_fit" && c.points >= 25) {
      chips.push({ label: "Shoulder season", title: c.reason });
    } else if (c.id === "offpeak_value" && c.points >= 15) {
      chips.push({ label: "Off-peak value", title: c.reason });
    } else if (c.id === "fare_drop" && c.points > 0) {
      chips.push({ label: "Fare dropped", title: c.reason });
    }
  }
  return chips;
}

const MONTH_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTH_LONG = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

/** [4,5,6,9,10,11,12] → "Apr–Jun · Sep–Dec" */
function fmtBestMonths(months: number[]): string {
  if (!months.length) return "";
  const sorted = [...months].sort((a, b) => a - b);
  const ranges: [number, number][] = [];
  let start = sorted[0];
  let prev = sorted[0];
  for (const m of sorted.slice(1)) {
    if (m === prev + 1) {
      prev = m;
    } else {
      ranges.push([start, prev]);
      start = m;
      prev = m;
    }
  }
  ranges.push([start, prev]);
  return ranges
    .map(([a, b]) => (a === b ? MONTH_SHORT[a - 1] : `${MONTH_SHORT[a - 1]}–${MONTH_SHORT[b - 1]}`))
    .join(" · ");
}

function fmtAsOf(iso: string): string {
  const d = new Date(`${iso}T00:00:00`);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export default function TrendingDestinations() {
  const [data, setData] = useState<DestinationsData | null>(null);
  const [galleries, setGalleries] = useState<GalleryData | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    loadDestinations().then(setData);
    loadGalleries().then(setGalleries);
  }, []);

  const bySlug = new Map((data?.destinations ?? []).map((d) => [d.slug, d]));
  const cards = (data?.trending_now ?? [])
    .map((slug) => bySlug.get(slug))
    .filter((d): d is TrendingDestination => !!d && isEligible(d))
    .slice(0, MAX_CARDS);

  const updateScrollState = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    setCanScrollLeft(el.scrollLeft > 10);
    setCanScrollRight(el.scrollLeft < el.scrollWidth - el.clientWidth - 10);
    const first = el.children[0] as HTMLElement | undefined;
    const step = first ? first.offsetWidth + GAP : el.clientWidth * 0.75;
    if (step > 0) {
      setCurrentIndex(Math.min(cards.length - 1, Math.max(0, Math.round(el.scrollLeft / step))));
    }
  }, [cards.length]);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    updateScrollState();
    el.addEventListener("scroll", updateScrollState, { passive: true });
    window.addEventListener("resize", updateScrollState);
    return () => {
      el.removeEventListener("scroll", updateScrollState);
      window.removeEventListener("resize", updateScrollState);
    };
  }, [cards.length, updateScrollState]);

  if (!data || cards.length === 0) return null;

  const monthLabel = `${MONTH_LONG[(data.current_month ?? 1) - 1] ?? ""} ${data.current_year}`;

  return (
    <section className="mb-12" id="trending-destinations">
      <div className="flex items-center justify-between gap-2 mb-2">
        <div className="flex items-center gap-2">
          <span className="text-xl">🔥</span>
          <h2 className="font-serif text-xl font-bold">Top Destinations to Visit</h2>
        </div>
        {cards.length > 1 && (
          <span
            aria-hidden
            className="text-[11px] font-semibold px-2.5 py-1 rounded-full bg-foreground/5 text-foreground/50"
            style={{ fontVariantNumeric: "tabular-nums" }}
          >
            {currentIndex + 1} / {cards.length}
          </span>
        )}
      </div>
      <p className="text-sm text-foreground/55 mb-5 max-w-2xl leading-relaxed">
        Trending now — {monthLabel}. Ranked by our destination tracker on
        season fit, value and fare movement; every card shows why it made the
        list.
      </p>

      <div className="relative">
        <style>{`.trending-rail::-webkit-scrollbar { display: none; }`}</style>

        {/* Edge fades — signal more content in that direction */}
        {canScrollLeft && (
          <div
            aria-hidden
            className="absolute top-0 bottom-0 left-0 w-14 z-[5] pointer-events-none"
            style={{ background: "linear-gradient(to right, hsl(var(--background)), hsl(var(--background) / 0))" }}
          />
        )}
        {canScrollRight && (
          <div
            aria-hidden
            className="absolute top-0 bottom-0 right-0 w-14 z-[5] pointer-events-none"
            style={{ background: "linear-gradient(to left, hsl(var(--background)), hsl(var(--background) / 0))" }}
          />
        )}

        <div
          ref={scrollRef}
          className="trending-rail flex gap-4 overflow-x-auto pb-4"
          style={{
            scrollSnapType: "x mandatory",
            WebkitOverflowScrolling: "touch",
            scrollbarWidth: "none",
            msOverflowStyle: "none",
          } as React.CSSProperties}
        >
          {cards.map((dest, i) => {
            const galleryPhoto = galleries?.[dest.slug]?.photos?.[0];
            const image = dest.hero_image || galleryPhoto?.src || null;
            const chips = reasonChips(dest);
            const best = fmtBestMonths(dest.best_months);
            return (
              <Link
                key={dest.slug}
                to={dest.guide_url}
                className="block group flex-shrink-0"
                style={{ width: "280px", scrollSnapAlign: "start" }}
              >
                <article className="bg-card border border-border rounded-xl overflow-hidden hover:border-primary/40 transition-all duration-200 hover:shadow-lg h-full flex flex-col">
                  <div className="relative h-40 overflow-hidden flex-shrink-0">
                    {image ? (
                      <img
                        src={image}
                        alt={galleryPhoto?.caption || dest.name}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                        loading="lazy"
                      />
                    ) : (
                      <div className="w-full h-full bg-[#0B1D3A] flex flex-col items-center justify-center gap-1">
                        <span className="font-serif text-5xl font-bold text-[#D4A843]">
                          {dest.name.charAt(0)}
                        </span>
                        <span className="text-[10px] font-semibold uppercase tracking-widest text-white/50">
                          {dest.region}
                        </span>
                      </div>
                    )}
                    <span className="absolute top-2 left-2 text-[11px] font-bold px-2 py-0.5 rounded-full bg-black/55 text-white backdrop-blur-sm">
                      #{i + 1} Trending
                    </span>
                  </div>

                  <div className="p-4 flex flex-col gap-2 flex-1">
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0">
                        <h3 className="font-serif font-bold text-base leading-tight group-hover:text-primary transition-colors">
                          {dest.name}
                        </h3>
                        <p className="text-[11px] text-foreground/50 leading-tight mt-0.5">{dest.region}</p>
                      </div>
                      <ChevronRight className="h-4 w-4 text-foreground/20 group-hover:text-primary transition-colors flex-shrink-0 mt-0.5" />
                    </div>

                    {chips.length > 0 && (
                      <div className="flex flex-wrap gap-1">
                        {chips.map((chip) => (
                          <span
                            key={chip.label}
                            title={chip.title}
                            className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-[#D4A843]/20 text-[#7a5c14] dark:text-[#D4A843]"
                          >
                            {chip.label}
                          </span>
                        ))}
                      </div>
                    )}

                    {best && (
                      <p className="text-[11px] text-foreground/55">
                        📅 Best: <span className="font-semibold text-foreground/75">{best}</span>
                      </p>
                    )}

                    {dest.highlights[0] && (
                      <p className="text-xs text-foreground/50 leading-snug line-clamp-2">
                        {dest.highlights[0].title}
                      </p>
                    )}

                    {dest.fare_from && (
                      <p className="mt-auto pt-1 text-[11px] font-semibold text-[#7a5c14] dark:text-[#D4A843]">
                        ✈️ {dest.fare_from.route} from ${dest.fare_from.price_min.toLocaleString()}
                        <span className="block text-[10px] font-normal text-foreground/40">
                          {dest.fare_from.date_range} · fares checked {fmtAsOf(dest.fare_from.as_of)}
                        </span>
                      </p>
                    )}
                  </div>
                </article>
              </Link>
            );
          })}
        </div>
      </div>
    </section>
  );
}
